if ( ! function_exists( 'wpbb_child_v83_metrics_markup' ) ) {
    function wpbb_child_v83_metrics_markup() {
        $c = wpbb_child_v83_config(); if ( empty( $c['metrics'] ) ) return '';
        $icons = array( '✦', '◎', '★' ); $out = '<div class="wpbb-v83-metrics-wrap" aria-label="' . esc_attr__( 'Key figures', 'wp-theme' ) . '"><div class="wpbb-v83-metrics">';
        foreach ( array_values( $c['metrics'] ) as $i => $metric ) {
            $out .= '<div class="wpbb-v83-metric"><span class="wpbb-v83-metric__icon" aria-hidden="true">' . esc_html( $icons[ $i % 3 ] ) . '</span><div><strong>' . esc_html( $metric[0] ) . '</strong><span>' . esc_html( wpbb_child_v83_metric_label( $metric[1] ) ) . '</span></div></div>';
        }
        return $out . '</div></div>';
    }
}
if ( ! function_exists( 'wpbb_child_v83_render_metrics' ) ) {
    function wpbb_child_v83_render_metrics( $block_content, $block ) {
        if ( is_admin() || ! is_front_page() || empty( $block['blockName'] ) || 'wpbb/bootstrap-div' !== $block['blockName'] ) return $block_content;
        $attrs = isset( $block['attrs'] ) && is_array( $block['attrs'] ) ? $block['attrs'] : array();
        $classes = (string) ( $attrs['utilityClasses'] ?? '' ) . ' ' . (string) ( $attrs['className'] ?? '' );
        if ( false === strpos( $classes, 'wp-theme-sector-hero' ) ) return $block_content;
        return $block_content . wpbb_child_v83_metrics_markup();
    }
    add_filter( 'render_block', 'wpbb_child_v83_render_metrics', 90, 2 );
}
