        if ( ! is_admin() || ! current_user_can( 'manage_options' ) ) return;
        $key = 'wpbb_child_v83_refresh_' . sanitize_key( get_stylesheet() );
        if ( '3.8.10.83' === (string) get_option( $key ) ) return;
        // Rebuild only pages explicitly marked as Starter Setup demo content.
        if ( function_exists( 'wpbb_child_v62_rebuild_demo_pages' ) ) wpbb_child_v62_rebuild_demo_pages( true );
        if ( function_exists( 'wpbb_child_381045_consistency_config' ) ) {
            $cfg = wpbb_child_381045_consistency_config();
            if ( $cfg ) {
                if ( function_exists( 'wpbb_child_381045_sync_sector_media' ) ) wpbb_child_381045_sync_sector_media( $cfg );
                if ( function_exists( 'wpbb_child_381045_sync_blog_media' ) ) wpbb_child_381045_sync_blog_media( $cfg );
                if ( function_exists( 'wpbb_child_381045_repair_demo_pages' ) ) wpbb_child_381045_repair_demo_pages( $cfg );
            }
        }
        // Keep all Starter Setup Polylang versions aligned to the repaired source.
        $front = absint( get_option( 'page_on_front' ) );
        $source_ids = array();
        if ( $front && get_post_meta( $front, '_wp_theme_demo_managed', true ) ) $source_ids[] = $front;
        foreach ( array( 'about', 'services', 'industries', 'contact' ) as $slug ) {
            $page = get_page_by_path( $slug );
            if ( $page instanceof WP_Post && get_post_meta( $page->ID, '_wp_theme_demo_managed', true ) ) $source_ids[] = $page->ID;
        }
        if ( $source_ids && function_exists( 'wpbb_child_v71_sync_managed_translations' ) ) wpbb_child_v71_sync_managed_translations( $source_ids );
        update_option( $key, '3.8.10.83', false );
    }
    add_action( 'admin_init', 'wpbb_child_v83_refresh_managed_demo', 245 );
    add_action( 'wp_theme_after_demo_import', 'wpbb_child_v83_refresh_managed_demo', 280 );
}
